  value: 10,
  transform: Math.log,
  label: tex`t_{max}`
})

y = {
  const output = [];

  let p; 
  let t0 = -0.5;
  //let tMax = 20;

  let t = t0;
  let d = 0;
  let u = 0;
  let i = 0;
  let e = 0;
  let eprev = e;
  let pu = u;
  let ppu = u;
  let du = 0;
  let ddu = 0;
  let pdu = 0;
  let y = 0;
  let py = 0;
  let ppy = 0;
  let dy = 0;
  let ddy = 0;
  let pdy = 0;
  let de = 0;
  let dt = 0.001;
  let s = setPoint(t0);
  output.push({ t, u, s });

  let j = 1;
  while (t &lt; tMax) {
    t = t0 + j * dt;

    s = setPoint(t);

    e = s - u;
    de = eprev-e;

    //du = (u-pu)/dt;
    //ddu = (du - pdu)/dt;

    //dy = (py - y)/dt;
    //ddy = (dy - pdy)/dt;

    p = e;
    i += e * dt;
    d = de/dt;

    y = s; //(Kp * p + Ki * i + Kd * d) * dt;

    u = (2*D*T*dt*pu + Kpt2*dt**2*y - T**2*ppu + 2*T**2*pu)/(2*D*T*dt + T**2 + dt**2);

    ppu = pu;
    pu = u;
    //pdu = du;

    //ppy = py;
    //py = y;
    //pdy = dy;

    eprev = e;

    output.push({ t, u, s });
    j++;
  }

  return output;
}

setPoint = {
  function hardstep(x) {
    return Math.max(0, Math.min(1, x));
  }
  function smoothstep(x) {
    var x = hardstep(x);
    return x * x * (3 - 2 * x);
  }
  switch (input) {
    case 'step':
      return t =&gt; (t &gt;= 0 ? 1 : 0);
    case 'ramp':
      return t =&gt; (t &gt;= 0 ? t : 0);
    case 'quadratic ramp':
      return t =&gt; (t &gt;= 0 ? t * t : 0);
    case 'smoothstep':
      return smoothstep;
    case 'hardstep':
      return hardstep;
    default:
      throw new Error('Invalid input');
  }
}

